import { readFileSync } from "node:fs";
import { join } from "node:path";
import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { EngineError } from "@nitro-forge/ignition";
import { CliHost } from "@nitro-forge/ignition/cli";
import { FolioDocument } from "../src/index";

// Fixture generated by `cargo run -p folio-engine --example
// gen_sigattach_fixture -- packages/folio/tests/fixtures/signatures.pdf`:
// one page, a signed Sig field, an unsigned Sig field, and one
// pre-existing EmbeddedFiles attachment ("readme.txt").
const fixtureBytes = () =>
  new Uint8Array(
    readFileSync(join(import.meta.dirname, "fixtures/signatures.pdf")),
  );

let host: CliHost;
beforeAll(() => {
  host = new CliHost();
});
afterAll(async () => {
  await host.dispose();
});

describe("folio signatures + attachments e2e (real Rust via nf-cli)", () => {
  it("lists signature fields with honest dictionary details", async () => {
    const doc = await FolioDocument.openPdf(host, fixtureBytes());
    const { signatures } = (await doc.listSignatures()).data;
    expect(signatures).toHaveLength(2);
    const signed = signatures.find((s) => s.name === "signature.signed")!;
    expect(signed).toMatchObject({
      page: 0,
      signed: true,
      byte_range: [0, 512, 1024, 2048],
      byte_range_well_formed: true,
      sub_filter: "adbe.pkcs7.detached",
      signer: "Fixture Signer",
      date: "D:20260102000000Z",
      reason: "fixture approval",
      contact: "signer@example.com",
      signature_type: "Sig",
    });
    expect(typeof signed.annot).toBe("number");
    const pending = signatures.find((s) => s.name === "signature.pending")!;
    expect(pending.signed).toBe(false);
    expect(pending.byte_range).toBeNull();
    const described = (await doc.describe<Record<string, unknown>>()).data;
    expect(described.signature_count).toBe(2);
    await doc.close();
  });

  it("lists and extracts a pre-existing attachment", async () => {
    const doc = await FolioDocument.openPdf(host, fixtureBytes());
    const { attachments } = (await doc.listAttachments()).data;
    expect(attachments).toHaveLength(1);
    expect(attachments[0]).toMatchObject({
      name: "readme.txt",
      description: "fixture notes",
    });
    expect(attachments[0]!.size).toBeGreaterThan(0);
    const got = await doc.getAttachment("readme.txt");
    expect(new TextDecoder().decode(got.bytes)).toBe(
      "fixture attachment bytes",
    );
    await expect(doc.getAttachment("missing.bin")).rejects.toBeInstanceOf(
      EngineError,
    );
    await doc.close();
  });

  it("adds an attachment with a PushPin annotation and persists", async () => {
    const doc = await FolioDocument.create(host, 1);
    const payload = new TextEncoder().encode("e2e attachment payload");
    await doc.addFileAttachment("notes.txt", payload, {
      description: "added by e2e",
      page: 0,
      rect: [50, 600, 20, 20],
    });
    let list = (await doc.listAttachments()).data.attachments;
    expect(list).toHaveLength(1);
    expect(list[0]).toMatchObject({
      name: "notes.txt",
      size: payload.length,
      description: "added by e2e",
    });
    const annots = (await doc.listAnnotations(0)).data.annots;
    expect(annots.some((a) => a.subtype === "FileAttachment")).toBe(true);

    // Duplicate name rejects.
    await expect(
      doc.addFileAttachment("notes.txt", new Uint8Array([1])),
    ).rejects.toBeInstanceOf(EngineError);

    // Save → reopen keeps name tree, filespec and annotation.
    const { bytes } = await doc.savePdf();
    const reopened = await FolioDocument.openPdf(host, bytes);
    list = (await reopened.listAttachments()).data.attachments;
    expect(list).toHaveLength(1);
    expect(list[0]!.name).toBe("notes.txt");
    const got = await reopened.getAttachment("notes.txt");
    expect(got.bytes).toEqual(payload);
    const annots2 = (await reopened.listAnnotations(0)).data.annots;
    expect(annots2.some((a) => a.subtype === "FileAttachment")).toBe(true);
    await reopened.close();
    await doc.close();
  });

  it("rejects attachment ops on encrypted documents", async () => {
    const doc = await FolioDocument.create(host, 1);
    await doc.addFileAttachment("a.txt", new Uint8Array([1, 2, 3]));
    await doc.encrypt({ password: "secret-pw" });
    await expect(doc.listAttachments()).rejects.toBeInstanceOf(EngineError);
    await expect(doc.getAttachment("a.txt")).rejects.toBeInstanceOf(
      EngineError,
    );
    await expect(
      doc.addFileAttachment("b.txt", new Uint8Array([4])),
    ).rejects.toBeInstanceOf(EngineError);
    await doc.close();
  });
});
